<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>The Observer Front Page</title>
<style>
    :root {
        --dark-blue: #0b1c3d;
        --banner-blue: #1b3d73;
        --banner-yellow: #f5e45a;
        --teaser-yellow: #ffec40;
        --teaser-pink: #d91c5c;
        --teaser-gold: #f4d030;
        --cyan: #00a4c2;
        --text-dark: #111;
        --border-color: #dcdcdc;
    }

    body {
        margin: 0;
        padding: 20px;
        background-color: #f0f0f0;
        font-family: 'Times New Roman', Times, serif;
    }

    .page-container {
        max-width: 1100px;
        margin: 0 auto;
        background-color: #fff;
        padding: 10px 15px 20px 15px;
        box-shadow: 0 0 10px rgba(0,0,0,0.1);
    }

    .placeholder {
        background-color: #eee;
        border: 1px dashed #999;
        display: flex;
        align-items: center;
        justify-content: center;
        color: #666;
        font-family: sans-serif;
        font-size: 12px;
        text-align: center;
        overflow: hidden;
    }

    /* Top Banner */
    .top-banner {
        background-color: var(--banner-blue);
        color: #fff;
        display: flex;
        justify-content: space-between;
        padding: 4px 15px;
        font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
        font-size: 15px;
        font-weight: bold;
        letter-spacing: 0.5px;
    }
    .top-banner .highlight {
        color: var(--banner-yellow);
    }

    /* Teasers Section */
    .teasers {
        display: flex;
        height: 280px;
        margin-top: 5px;
        margin-bottom: 5px;
    }

    .teaser-1 {
        flex: 2.2;
        background-color: var(--teaser-yellow);
        position: relative;
        padding: 15px;
        color: var(--dark-blue);
        overflow: hidden;
        border-right: 2px solid #fff;
    }
    .teaser-1 .mag-cover {
        position: absolute;
        left: -15px;
        top: 15px;
        width: 170px;
        height: 230px;
        transform: rotate(-4deg);
        box-shadow: 2px 2px 5px rgba(0,0,0,0.3);
    }
    .teaser-1 .text-content {
        margin-left: 170px;
        margin-right: 80px;
    }
    .teaser-1 h2 {
        font-size: 58px;
        font-weight: 900;
        line-height: 0.9;
        margin: 0 0 15px 0;
        letter-spacing: -1px;
    }
    .teaser-1 p.sub {
        font-family: 'Georgia', serif;
        font-size: 16px;
        font-weight: bold;
        color: #b32128;
        line-height: 1.2;
        margin: 0 0 15px 0;
    }
    .teaser-1 p.footer {
        font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
        font-style: italic;
        font-size: 13px;
        font-weight: bold;
        margin: 0;
    }
    .teaser-1 .person {
        position: absolute;
        right: 10px;
        bottom: 0;
        width: 130px;
        height: 250px;
        border: none;
        background: transparent;
    }

    .teaser-right-group {
        flex: 1.8;
        display: flex;
    }

    .teaser-2 {
        flex: 1;
        background-color: var(--teaser-pink);
        padding: 10px;
        color: #fff;
        display: flex;
        flex-direction: column;
        border-right: 2px solid #fff;
        position: relative;
    }
    .teaser-2 .mag-cover-small {
        width: 100px;
        height: 130px;
        margin: 0 auto 10px auto;
        box-shadow: 1px 1px 4px rgba(0,0,0,0.4);
    }
    .teaser-2 h3 {
        font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
        font-size: 20px;
        margin: 0 0 5px 0;
        line-height: 1;
        color: var(--banner-yellow);
    }
    .teaser-2 p {
        font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
        font-size: 13px;
        font-weight: bold;
        line-height: 1.2;
        margin: 0 0 auto 0;
    }
    .teaser-2 p.footer {
        font-style: italic;
        font-size: 12px;
        color: var(--banner-yellow);
        margin: 5px 0 0 0;
    }

    .teaser-3-wrapper {
        flex: 1;
        display: flex;
        flex-direction: column;
    }
    .teaser-3 {
        flex: 1;
        background-color: var(--teaser-gold);
        padding: 10px;
        position: relative;
        display: flex;
        flex-direction: column;
    }
