        font-size: 12px;
        font-weight: bold;
        margin: auto 0 0 0;
        color: var(--text-dark);
    }

    .barcode-container {
        height: 40px;
        background: #fff;
        display: flex;
        justify-content: center;
        align-items: center;
        padding-top: 5px;
    }
    .barcode {
        width: 120px;
        height: 35px;
    }

    /* Masthead */
    .masthead {
        display: flex;
        justify-content: space-between;
        align-items: flex-end;
        border-bottom: 3px solid var(--dark-blue);
        padding-bottom: 5px;
        margin-bottom: 15px;
    }
    .masthead h1 {
        font-size: 105px;
