        margin-bottom: 15px;
        border-bottom: 1px solid var(--border-color);
        padding-bottom: 15px;
    }

    .left-headline h2 {
        font-size: 52px;
        font-weight: normal;
        margin: 0;
        line-height: 1.05;
        color: var(--text-dark);
        letter-spacing: -0.5px;
    }

    .right-headline h2 {
        font-size: 32px;
        font-weight: normal;
        margin: 0;
        line-height: 1.05;
        color: var(--text-dark);
        letter-spacing: -0.5px;
    }

    /* Columns Setup */
    .col {
        display: flex;
        flex-direction: column;
    }
    .col-divider-right {
        border-right: 1px solid var(--border-color);
        padding-right: 15px;
    }

    /* Column 1 Content */
    .bullets {
        list-style: none;
        padding: 0;
        margin: 0 0 15px 0;
    }
    .bullets li {
        font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
        font-size: 16px;
        font-weight: normal;
        color: var(--text-dark);
        margin-bottom: 6px;
        display: flex;
        align-items: flex-start;
        line-height: 1.2;
    }
    .bullets li::before {
        content: "⬟";
        color: var(--cyan);
        font-size: 14px;
        margin-right: 8px;
        margin-top: 1px;
    }

    .author-block {
        border-top: 2px solid var(--text-dark);
        border-bottom: 1px solid var(--text-dark);
        padding: 8px 0;
        margin-bottom: 12px;
        font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
    }
    .author-block strong {
        display: block;
        font-size: 13px;
        font-weight: 800;
    }
    .author-block em {
        display: block;
        font-size: 12px;
        font-style: italic;
        color: #555;
        margin-top: 2px;
    }

    .body-text {
        font-size: 13.5px;
        line-height: 1.35;
        color: #222;
        text-align: justify;
    }
    .body-text p {
        margin: 0 0 12px 0;
        text-indent: 15px;
    }
    .body-text p:first-of-type {
        text-indent: 0;
    }

    /* Mid Section (Cols 2 & 3 equivalent) */
    .mid-content {
        display: flex;
        flex-direction: column;
    }

    .mid-top {
        display: flex;
        gap: 15px;
        margin-bottom: 15px;
    }

    .mid-top-img-area {
        flex: 2.2;
    }
    .main-img {
        width: 100%;
        height: 280px;
        background-color: #ddd;
    }

    .mid-top-quote-area {
        flex: 1;
        display: flex;
        flex-direction: column;
    }
    .img-caption {
        font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
        font-size: 11px;
        font-weight: bold;
        line-height: 1.3;
        color: #333;
        margin-bottom: 15px;
    }
    .quote-box {
        background-color: #e8f4f7;
        padding: 12px;
        border-top: 4px solid var(--cyan);
        font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
    }
    .quote-box h4 {
        color: var(--cyan);
        margin: 0 0 6px 0;
        font-size: 15px;
        font-weight: 800;
    }
    .quote-box p.quote-text {
        font-size: 16px;
        font-weight: 800;
        line-height: 1.15;
        color: #000;
        margin: 0 0 10px 0;
    }
    .quote-box p.quote-link {
        color: var(--cyan);
        font-size: 12px;
        font-style: italic;
        font-weight: 800;
        margin: 0;
    }

    .mid-bottom {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 20px;
    }

    /* Rightmost Column */
    .col-4 .author-block {
        border-top: 2px solid var(--text-dark);
        border-bottom: none;
        padding-bottom: 0;
    }

    .continued {
        text-align: right;
        font-style: italic;
        font-size: 11px;
        font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
        color: #555;
        margin-top: 5px;
        font-weight: bold;
    }
</style>
</head>
